void handle_timer_callback(struct snd_timer_instance *timeri, int event,
                           struct timespec *tstamp, unsigned long resolution)
{
    if (event < 0 || event >= SNDRV_TIMER_EVENT_MAX)
        return;

    if (!timeri->queue || !timeri->queue->read)
        return;

    if (timeri->filter && !(timeri->filter & (1 << event)))
        return;

    if (tstamp)
        timeri->tstamp = *tstamp;

    struct snd_timer_read read;
    read.event = event;
    read.tstamp = timeri->tstamp;
    read.resolution = resolution;

    spin_lock_irq(&timeri->queue->lock);
    list_add_tail(&read.node, &timeri->queue->reads);
    spin_unlock_irq(&timeri->queue->lock);

    wake_up(&timeri->queue->wait);
    wake_up(&timeri->queue->sleep);
}

void handle_timer_event(struct snd_timer_instance *timeri, int event,
                        struct timespec *tstamp, unsigned long resolution)
{
    if (event < 0 || event >= SND_TIMER_EVENT_MAX)
        return;

    if (!timeri->client || !timeri->queue)
        return;

    if (timeri->filter & (1 << event)) {
        struct snd_timer_read *tr;

        tr = kmalloc(sizeof(*tr), GFP_KERNEL);
        if (!tr)
            return;

        tr->resolution = resolution;
        tr->event = event;
        tr->tstamp = *tstamp;

        spin_lock_irq(&timeri->queue->lock);
        list_add_tail(&tr->list, &timeri->queue->reads);
        spin_unlock_irq(&timeri->queue->lock);

        wake_up(&timeri->queue->wait);
        wake_up(&timeri->queue->sleep);
    }
}

void handle_timer_event(struct snd_timer_instance *timeri, int event, struct timespec *tstamp, unsigned long resolution)
{
    if (event < 0 || event >= SNDRV_TIMER_EVENT_MAX)
        return;

    if (tstamp)
        timeri->timestamp = *tstamp;

    if (!(timeri->filter & (1 << event)))
        return;

    if (!snd_timer_read_available(timeri))
        return;

    struct snd_timer_read read;
    read.event = event;
    read.tstamp = timeri->timestamp;

    spin_lock_irq(&timeri->queue_lock);
    snd_timer_queue_append(timeri, &read);
    spin_unlock_irq(&timeri->queue_lock);

    wake_up(&timeri->wait_queue);
    wake_up_interruptible(&timeri->sleep_queue);
}

void handle_timer_event(struct snd_timer_instance *timeri, int event, struct timespec *tstamp, unsigned long resolution)
{
    if (event < SNDRV_TIMER_EVENT_START || event > SNDRV_TIMER_EVENT_PAUSE)
        return;

    if (timeri->filter && !(timeri->filter & (1 << event)))
        return;

    if (!timeri->read)
        return;

    struct snd_timer_read read;
    read.event = event;
    read.tstamp = *tstamp;

    spin_lock(&timeri->queue_lock);
    list_add_tail(&read.list, &timeri->queue);
    spin_unlock(&timeri->queue_lock);

    wake_up(&timeri->queue_wait);
    wake_up_interruptible(&timeri->sleep_wait);
}

void handle_timer_callback(struct snd_timer_instance *timeri, int event, struct timespec *tstamp, unsigned long resolution) {
